import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineBulkDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';
import { isValidDate } from './dates.js';

export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => a.dueDate.localeCompare(b.dueDate));
}

export function vatSummary(invoices) {
  const vatMap = new Map();

  const relevantInvoices = invoices.filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid');

  for (const invoice of relevantInvoices) {
    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const base = Math.max(0, lineTotal(line) - lineDiscount(line) - lineBulkDiscount(line));
      const vat = lineVAT(line);

      if (!vatMap.has(rate)) {
        vatMap.set(rate, { rate, base: 0, vat: 0 });
      }

      const entry = vatMap.get(rate);
      entry.base = roundCents(entry.base + base);
      entry.vat = roundCents(entry.vat + vat);
    }
  }

  return Array.from(vatMap.values()).sort((a, b) => b.rate - a.rate);
}

export function lateFee(invoice, asOf) {
  if (!invoice.dueDate || !isValidDate(asOf)) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  if (daysOverdue <= 0) {
    return 0;
  }

  const amountDue = balanceDue(invoice);
  const fee = roundCents(amountDue * 0.0004 * daysOverdue);

  return Math.max(0, fee);
}

