import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('overdueInvoices returns invoices with dueDate before asOf', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices excludes invoices not yet due', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-03-15',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 0);
});

test('overdueInvoices excludes invoices due on asOf date', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-03-01',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 0);
});

test('overdueInvoices excludes draft invoices', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'draft',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'paid',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
      // With bulk discount: total = 95000 - 2375 + 19451 = 112076
      payments: [{ amount: 112076, date: '2026-02-10' }],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 0);
});

test('overdueInvoices includes issued invoices', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 1);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'partially_paid',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
      payments: [{ amount: 50000, date: '2026-02-10' }],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 1);
});

test('overdueInvoices sorts by dueDate ascending (most overdue first)', () => {
  const invoices = [
    {
      number: 'INV-2026-0002',
      customerId: 'C-001',
      issueDate: '2026-02-15',
      dueDate: '2026-03-15',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-04-01');

  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[1].number, 'INV-2026-0002');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-02-24');

  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices calculates due correctly for unpaid invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  // With bulk discount: total = 95000 - 2375 + 19451 = 112076
  assert.equal(result[0].due, 112076);
});

test('overdueInvoices calculates due correctly for partially paid invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'partially_paid',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
      payments: [{ amount: 50000, date: '2026-02-10' }],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  // With bulk discount: total = 95000 - 2375 + 19451 = 112076
  // Due = 112076 - 50000 = 62076
  assert.equal(result[0].due, 62076);
});

test('overdueInvoices includes all required fields', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 1);
  const inv = result[0];
  assert(inv.hasOwnProperty('number'));
  assert(inv.hasOwnProperty('customerId'));
  assert(inv.hasOwnProperty('dueDate'));
  assert(inv.hasOwnProperty('daysOverdue'));
  assert(inv.hasOwnProperty('due'));
});

test('overdueInvoices returns empty array when no invoices overdue', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-03-15',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
